<?php require_once 'config/config.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:index.php');exit;}verify_csrf();$f=trim($_POST['first_name']??'');$l=trim($_POST['last_name']??'');$email=strtolower(trim($_POST['email']??''));$p=$_POST['password']??'';$cp=$_POST['confirm_password']??'';if(!$f||!$l||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($p)<8||$p!==$cp){flash('danger','Please complete the form correctly.');header('Location:index.php');exit;}$s=db()->prepare("SELECT id FROM users WHERE email=?");$s->execute([$email]);if($s->fetch()){flash('danger','That email is already registered.');header('Location:index.php');exit;}$s=db()->prepare("INSERT INTO users(first_name,last_name,email,password) VALUES(?,?,?,?)");$s->execute([$f,$l,$email,password_hash($p,PASSWORD_DEFAULT)]);$id=(int)db()->lastInsertId();session_regenerate_id(true);$_SESSION['user']=['id'=>$id,'first_name'=>$f,'last_name'=>$l,'email'=>$email,'role'=>'user'];activity($id,'register','Account created');flash('success','Welcome to FoodFusion.');header('Location:dashboard.php');